Both `Leads.tsx` and `DispensaryMap.tsx` call `reps.find()` for every item rendered — O(n×m) total.

```tsx
// ❌ Both files — linear scan per item
const repName = (id: string | null) => reps.find(r => r.id === id)?.name ?? '—'
```

```tsx
// ✅ Build a Map once after data loads
const repMap = useMemo(() => new Map(reps.map(r => [r.id, r.name])), [reps])
const repName = (id: string | null) => repMap.get(id ?? '') ?? '—'
```

```tsx
// ❌ Runs on every render including unrelated state changes (showModal, saving)
const byStage = STAGES.reduce<Record<Stage, Lead[]>>((acc, s) => {
  acc[s.value] = leads.filter(l => l.stage === s.value)
  return acc
}, {} as Record<Stage, Lead[]>)
```

```tsx
// ✅ Single-pass with useMemo
const byStage = useMemo(() => {
  const acc: Record<Stage, Lead[]> = { cold: [], sampled: [], first_order: [], repeat: [] }
  for (const lead of leads) acc[lead.stage].push(lead)
  return acc
}, [leads])
```

```tsx
// ❌ Runs on every render
const filtered = filterRegion ? stores.filter(s => s.region === filterRegion) : stores
```

```tsx
// ✅
const filtered = useMemo(
  () => filterRegion ? stores.filter(s => s.region === filterRegion) : stores,
  [stores, filterRegion]
)
```

```tsx
// ❌ Inline objects create new references, forcing reconciliation
style={{ background: 'radial-gradient(...)', top: '-10%', left: '-5%', animation: 'drift1 18s...' }}
```
Move these to a CSS class or extract them as module-level constants so they're stable references.

---

Every page navigation triggers fresh Supabase fetches. The `reps` list is loaded in at least 4 pages (Leads, DispensaryMap, Reps, Dashboard). A lightweight context or React Query would eliminate this:

```tsx
// Simple shared context (no extra deps)
const RepsContext = createContext<Rep[]>([])
export function RepsProvider({ children }) {
  const [reps, setReps] = useState<Rep[]>([])
  useEffect(() => {
    supabase.from('reps').select('*').order('name').then(({ data }) => setReps(data ?? []))
  }, [])
  return <RepsContext.Provider value={reps}>{children}</RepsContext.Provider>
}
```

```tsx
// ❌ Recalculates on every parent render (slider drag triggers many renders)
function CalcResult({ units, tier, rate, hasBonus, storeCount }) {
  const price = tier === 'list' ? LIST_PRICE : FLOOR_PRICE
  const gross = units * price
  // ...
```

```tsx
// ✅ Memoize the component since all inputs are primitives
export const CalcResult = memo(function CalcResult({ units, tier, rate, hasBonus, storeCount }) { ... })
```

