```tsx
// ❌ If component unmounts in <2s, sets state on unmounted component
const saveRoute = async () => {
  // ...
  setSaved(true)
  setTimeout(() => setSaved(false), 2000)  // no cleanup
}
```

```tsx
// ✅ Use a ref to track and cancel the timer
const timerRef = useRef<ReturnType<typeof setTimeout>>()

useEffect(() => () => clearTimeout(timerRef.current), [])

const saveRoute = async () => {
  // ...
  setSaved(true)
  timerRef.current = setTimeout(() => setSaved(false), 2000)
}
```

```tsx
// ❌ New Date parse on every render
const daysLeft = daysUntil(BATCH_EXPIRES)
```

```tsx
// ✅ Stable since BATCH_EXPIRES is a constant
const daysLeft = useMemo(() => daysUntil(BATCH_EXPIRES), [])
```

